IF RTrigger1Open.Q THEN
  bCylinder1Open:= FALSE;(*资源回收*)
  g_bCylinderOpen1:= FALSE;(*资源回收*)
  g_boLoadCyl01Up := TRUE;
  g_boLoadCyl01Down := FALSE;
  g_bLoadMaterial1DelayFlag := TRUE;
  g_bLoadMaterialState1:= FALSE;
  g_boLoading1UpDone:= FALSE;
  g_boLoading1DownDone:= FALSE;
  bLoadMaterial1UpDelayFlag := TRUE;
  bLoadMaterial1DownDelayFlag := FALSE;
  InDownPlaceAlarm0(IN :=FALSE);
  InPlaceDelay0(IN :=FALSE);
  g_bLoadCylinder1DownSignalInplaceTimeoutAlarm:=FALSE;
END_IF;
IF RTrigger1Close.Q THEN
  bCylinder1Close:= FALSE;(*资源回收*)
  g_bCylinderClose1:= FALSE;(*资源回收*)
  g_boLoadCyl01Up := FALSE;
  g_boLoadCyl01Down := TRUE;
  g_bLoadMaterial1DelayFlag := TRUE;
  g_bLoadMaterialState1:= FALSE;
  g_boLoading1UpDone:= FALSE;
  g_boLoading1DownDone:= FALSE;
  bLoadMaterial1UpDelayFlag := FALSE ;
  bLoadMaterial1DownDelayFlag := TRUE;
  InUpPlaceAlarm0(IN :=FALSE);
  InPlaceDelay0(IN :=FALSE);
  g_bLoadCylinder1UpSignalInplaceTimeoutAlarm:=FALSE;
END_IF;

IF g_bLoadMaterialUpInPlaceSignal1 THEN (*使用上升到位信号*)
  IF g_boLoadCyl01Up AND g_boLoadCyl01Down=FALSE THEN
    InPlaceDelay0(IN :=FALSE);
    IF g_bLoadCyl01UpInPlace AND g_bLoadCyl02UpInPlace AND g_bLoadCyl03UpInPlace AND g_bLoadCyl04UpInPlace THEN
      g_bLoadMaterialStateHmi1:= TRUE;
      g_bLoadMaterialState1:= TRUE;
      g_boLoading1UpDone:= TRUE;
      InUpPlaceAlarm0(IN :=FALSE);
      g_bLoadCylinder1UpSignalInplaceTimeoutAlarm:=FALSE;
    ELSE
      IF NOT g_bLoadMaterialStateHmi1 THEN
        InUpPlaceAlarm0(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nLoadMaterialUpInPlaceDelay1)));
        IF InUpPlaceAlarm0.Q THEN
          InUpPlaceAlarm0(IN :=FALSE);
          g_bLoadCylinder1UpSignalInplaceTimeoutAlarm:=TRUE;
        END_IF;
      END_IF;        
    END_IF;
    IF NOT g_CylAllStateUpDate.BoolArr[1] AND g_bLoadMaterialStateHmi1 THEN
      g_bLoadCylinder1UpSignalInplaceTimeoutAlarm:=TRUE;
    ELSIF g_CylAllStateUpDate.BoolArr[1] AND g_bLoadMaterialStateHmi1 THEN
      g_bLoadCylinder1UpSignalInplaceTimeoutAlarm:=FALSE;
    END_IF; 
  END_IF;
ELSE(*使用上升到位延时*)
   g_bLoadCylinder1UpSignalInplaceTimeoutAlarm:=FALSE;
   IF bLoadMaterial1UpDelayFlag THEN
    InPlaceDelay0(IN :=g_boLoadCyl01Up,PT := LREAL_TO_TIME(FUN_MStoS(g_nLoadMaterialUpInPlaceDelay1)));
    IF InPlaceDelay0.Q THEN
      g_bLoadMaterial1DelayFlag := FALSE;
      bLoadMaterial1UpDelayFlag := FALSE;
      InPlaceDelay0(IN :=FALSE);
      IF g_boLoadCyl01Up AND g_boLoadCyl01Down=FALSE THEN
        g_bLoadMaterialStateHmi1:= TRUE;
        g_bLoadMaterialState1:= TRUE;
        g_boLoading1UpDone:= TRUE;
      END_IF;
    END_IF;
  END_IF;
END_IF;

IF g_bLoadMaterialDownInPlaceSignal1 THEN(*使用下降到位信号*)
  IF g_boLoadCyl01Down AND g_boLoadCyl01Up=FALSE THEN
    InPlaceDelay0(IN :=FALSE);
    IF g_bLoadCyl01DownInPlace AND g_bLoadCyl02DownInPlace AND g_bLoadCyl03DownInPlace AND g_bLoadCyl04DownInPlace THEN
      g_bLoadMaterialStateHmi1:= FALSE;
      g_bLoadMaterialState1:= TRUE;
      g_boLoading1DownDone:= TRUE;
      InDownPlaceAlarm0(IN :=FALSE);
      g_bLoadCylinder1DownSignalInplaceTimeoutAlarm:=FALSE;
    ELSE
      IF g_bLoadMaterialStateHmi1 THEN
        InDownPlaceAlarm0(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_nLoadMaterialDownInPlaceDelay1)));
        IF InDownPlaceAlarm0.Q THEN
          InDownPlaceAlarm0(IN :=FALSE);
          g_bLoadCylinder1DownSignalInplaceTimeoutAlarm:=TRUE;
        END_IF;
      END_IF;   
    END_IF;
    IF NOT g_CylAllStateUpDate.BoolArr[0] AND NOT g_bLoadMaterialStateHmi1 THEN
      g_bLoadCylinder1DownSignalInplaceTimeoutAlarm:=TRUE;
    ELSIF g_CylAllStateUpDate.BoolArr[0] AND NOT g_bLoadMaterialStateHmi1 THEN
      g_bLoadCylinder1DownSignalInplaceTimeoutAlarm:=FALSE;
    END_IF; 
  END_IF;
ELSE(*使用下降到位延时*)
   g_bLoadCylinder1DownSignalInplaceTimeoutAlarm:=FALSE;
   IF bLoadMaterial1DownDelayFlag THEN
    InPlaceDelay0(IN :=g_boLoadCyl01Down,PT := LREAL_TO_TIME(FUN_MStoS(g_nLoadMaterialDownInPlaceDelay1)));
    IF InPlaceDelay0.Q THEN
      InPlaceDelay0(IN :=FALSE);
      bLoadMaterial1DownDelayFlag := FALSE;
      g_bLoadMaterial1DelayFlag := FALSE;
      IF g_boLoadCyl01Down AND g_boLoadCyl01Up=FALSE THEN
        g_bLoadMaterialStateHmi1:= FALSE;
        g_bLoadMaterialState1:= TRUE;
        g_boLoading1DownDone:= TRUE;
      END_IF;
    END_IF;
  END_IF;
END_IF;



